CREATE TABLE IF NOT EXISTS sys_dict_type (id CHAR(26) PRIMARY KEY, dict_code VARCHAR(80) NOT NULL UNIQUE, dict_name VARCHAR(120) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS sys_dict_item (id CHAR(26) PRIMARY KEY, type_id CHAR(26) NOT NULL, item_value VARCHAR(80) NOT NULL, item_label VARCHAR(120) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, sort_order INT NOT NULL DEFAULT 0, CONSTRAINT fk_dict_item_type FOREIGN KEY(type_id) REFERENCES sys_dict_type(id));
